using Alafe.Api.Models;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Alafe.Api.Data.Configurations;

public sealed class MonedaConfiguration : IEntityTypeConfiguration<Moneda> { public void Configure(EntityTypeBuilder<Moneda> b) { b.ToTable("Monedas"); b.HasKey(x=>x.Codigo).HasName("PK_Monedas"); b.Property(x=>x.Codigo).HasColumnType("char(3)").HasMaxLength(3).IsFixedLength().IsUnicode(false); b.Property(x=>x.Nombre).HasMaxLength(50).IsRequired(); b.Property(x=>x.Simbolo).HasMaxLength(5).IsRequired(); b.Property(x=>x.HabilitadaEnAgenda).HasDefaultValue(false); b.Property(x=>x.HabilitadaEnMovimiento).HasDefaultValue(true); b.Property(x=>x.Activo).HasDefaultValue(true); } }
public sealed class PaisConfiguration : IEntityTypeConfiguration<Pais> { public void Configure(EntityTypeBuilder<Pais> b) { b.ToTable("Paises"); b.HasKey(x=>x.Codigo).HasName("PK_Paises"); b.Property(x=>x.Codigo).HasColumnType("char(2)").HasMaxLength(2).IsFixedLength().IsUnicode(false); b.Property(x=>x.Nombre).HasMaxLength(80).IsRequired(); b.Property(x=>x.CodigoLada).HasMaxLength(6).IsRequired(); b.Property(x=>x.MonedaDefaultCodigo).HasColumnType("char(3)").HasMaxLength(3).IsFixedLength().IsUnicode(false); b.Property(x=>x.Activo).HasDefaultValue(true); b.HasIndex(x=>x.Nombre).IsUnique().HasDatabaseName("UQ_Paises_Nombre"); b.HasOne(x=>x.MonedaDefault).WithMany(x=>x.Paises).HasForeignKey(x=>x.MonedaDefaultCodigo).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_Paises_Monedas"); } }
public sealed class PlanConfiguration : IEntityTypeConfiguration<Plan> { public void Configure(EntityTypeBuilder<Plan> b) { b.ToTable("Planes",t=>{t.HasCheckConstraint("CK_Planes_PrecioMensual","PrecioMensual >= 0");t.HasCheckConstraint("CK_Planes_LimiteAgendas","LimiteAgendas IS NULL OR LimiteAgendas >= 1");t.HasCheckConstraint("CK_Planes_LimiteUsuarios","LimiteUsuarios IS NULL OR LimiteUsuarios >= 1");}); b.HasKey(x=>x.Id).HasName("PK_Planes"); b.Property(x=>x.Codigo).HasMaxLength(30).IsRequired(); b.Property(x=>x.Nombre).HasMaxLength(60).IsRequired(); b.Property(x=>x.Descripcion).HasMaxLength(250); b.Property(x=>x.PrecioMensual).HasPrecision(10,2); b.Property(x=>x.MonedaCodigo).HasColumnType("char(3)").HasMaxLength(3).IsFixedLength().IsUnicode(false).HasDefaultValue("MXN"); b.Property(x=>x.IncluyeMovimientos).HasDefaultValue(false); b.Property(x=>x.IncluyeReportes).HasDefaultValue(false); b.Property(x=>x.IncluyeInventario).HasDefaultValue(false); b.Property(x=>x.OrdenVisual).HasDefaultValue(1); b.Property(x=>x.Activo).HasDefaultValue(true); b.HasIndex(x=>x.Codigo).IsUnique().HasDatabaseName("UQ_Planes_Codigo"); b.HasIndex(x=>x.Nombre).IsUnique().HasDatabaseName("UQ_Planes_Nombre"); b.HasOne(x=>x.Moneda).WithMany(x=>x.Planes).HasForeignKey(x=>x.MonedaCodigo).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_Planes_Monedas"); } }
public sealed class PermisoConfiguration : IEntityTypeConfiguration<Permiso> { public void Configure(EntityTypeBuilder<Permiso> b) { b.ToTable("Permisos"); b.HasKey(x=>x.Id).HasName("PK_Permisos"); b.Property(x=>x.Clave).HasMaxLength(60).IsRequired(); b.Property(x=>x.Modulo).HasMaxLength(40).IsRequired(); b.Property(x=>x.Descripcion).HasMaxLength(200); b.HasIndex(x=>x.Clave).IsUnique().HasDatabaseName("UQ_Permisos_Clave"); } }
public sealed class PropietarioConfiguration : IEntityTypeConfiguration<Propietario> { public void Configure(EntityTypeBuilder<Propietario> b) { b.ToTable("Propietarios",t=>t.HasCheckConstraint("CK_Propietarios_EstadoSuscripcion","EstadoSuscripcion IN (N'Activa',N'Prueba',N'Suspendida',N'Cancelada')")); b.HasKey(x=>x.Id).HasName("PK_Propietarios"); b.Property(x=>x.NombreEspacioTrabajo).HasMaxLength(150).IsRequired(); b.Property(x=>x.CorreoTitular).HasMaxLength(256).IsRequired(); b.Property(x=>x.PaisCodigo).HasColumnType("char(2)").HasMaxLength(2).IsFixedLength().IsUnicode(false).HasDefaultValue("MX"); b.Property(x=>x.TelefonoPaisCodigo).HasColumnType("char(2)").HasMaxLength(2).IsFixedLength().IsUnicode(false).HasDefaultValue("MX"); b.Property(x=>x.TelefonoContacto).HasMaxLength(20).IsRequired(); b.Property(x=>x.EstadoSuscripcion).HasMaxLength(20).HasDefaultValue("Activa"); b.Property(x=>x.FechaInicioSuscripcion).HasPrecision(3).HasDefaultValueSql("SYSUTCDATETIME()"); b.Property(x=>x.Activo).HasDefaultValue(true); b.Property(x=>x.FechaCreacion).HasPrecision(3).HasDefaultValueSql("SYSUTCDATETIME()"); b.Property(x=>x.FechaActualizacion).HasPrecision(3); b.HasIndex(x=>x.PlanId).HasDatabaseName("IX_Propietarios_PlanId"); b.HasOne(x=>x.Plan).WithMany(x=>x.Propietarios).HasForeignKey(x=>x.PlanId).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_Propietarios_Planes"); b.HasOne(x=>x.Pais).WithMany(x=>x.Propietarios).HasForeignKey(x=>x.PaisCodigo).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_Propietarios_Paises"); b.HasOne(x=>x.TelefonoPais).WithMany(x=>x.PropietariosTelefono).HasForeignKey(x=>x.TelefonoPaisCodigo).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_Propietarios_TelefonoPais"); } }
public sealed class RolConfiguration : IEntityTypeConfiguration<Rol> { public void Configure(EntityTypeBuilder<Rol> b) { b.ToTable("Roles"); b.HasKey(x=>x.Id).HasName("PK_Roles"); b.Property(x=>x.Nombre).HasMaxLength(50).IsRequired(); b.Property(x=>x.Descripcion).HasMaxLength(200); b.Property(x=>x.EsSistema).HasDefaultValue(false); b.Property(x=>x.Activo).HasDefaultValue(true); b.Property(x=>x.FechaCreacion).HasPrecision(3).HasDefaultValueSql("SYSUTCDATETIME()"); b.Property(x=>x.FechaActualizacion).HasPrecision(3); b.HasIndex(x=>new{x.PropietarioId,x.Nombre}).IsUnique().HasDatabaseName("UQ_Roles_Propietario_Nombre"); b.HasOne(x=>x.Propietario).WithMany(x=>x.Roles).HasForeignKey(x=>x.PropietarioId).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_Roles_Propietarios"); } }
public sealed class RolPermisoConfiguration : IEntityTypeConfiguration<RolPermiso> { public void Configure(EntityTypeBuilder<RolPermiso> b) { b.ToTable("RolPermisos"); b.HasKey(x=>new{x.RolId,x.PermisoId}).HasName("PK_RolPermisos"); b.HasIndex(x=>x.PermisoId).HasDatabaseName("IX_RolPermisos_PermisoId"); b.HasOne(x=>x.Rol).WithMany(x=>x.RolPermisos).HasForeignKey(x=>x.RolId).OnDelete(DeleteBehavior.Cascade).HasConstraintName("FK_RolPermisos_Roles"); b.HasOne(x=>x.Permiso).WithMany(x=>x.RolPermisos).HasForeignKey(x=>x.PermisoId).OnDelete(DeleteBehavior.Cascade).HasConstraintName("FK_RolPermisos_Permisos"); } }
public sealed class UsuarioConfiguration : IEntityTypeConfiguration<Usuario> { public void Configure(EntityTypeBuilder<Usuario> b) { b.ToTable("Usuarios",t=>{t.HasCheckConstraint("CK_Usuarios_TokenVersion","TokenVersion >= 1");t.HasCheckConstraint("CK_Usuarios_TemaVisual","TemaVisual IN (N'claro',N'oscuro')");t.HasCheckConstraint("CK_Usuarios_VistaAgendaDefault","VistaAgendaDefault IN (N'mes',N'lista')");}); b.HasKey(x=>x.Id).HasName("PK_Usuarios"); b.Property(x=>x.NombreCompleto).HasMaxLength(150).IsRequired(); b.Property(x=>x.Correo).HasMaxLength(256).IsRequired(); b.Property(x=>x.TelefonoPaisCodigo).HasColumnType("char(2)").HasMaxLength(2).IsFixedLength().IsUnicode(false).HasDefaultValue("MX"); b.Property(x=>x.Telefono).HasMaxLength(20).IsRequired(); b.Property(x=>x.PasswordHash).HasMaxLength(512).IsRequired(); b.Property(x=>x.EsPropietario).HasDefaultValue(false); b.Property(x=>x.TokenVersion).HasDefaultValue(1); b.Property(x=>x.Activo).HasDefaultValue(true); b.Property(x=>x.UltimoAcceso).HasPrecision(3); b.Property(x=>x.TemaVisual).HasMaxLength(20).HasDefaultValue("claro"); b.Property(x=>x.VistaAgendaDefault).HasMaxLength(10).HasDefaultValue("mes"); b.Property(x=>x.FechaCreacion).HasPrecision(3).HasDefaultValueSql("SYSUTCDATETIME()"); b.Property(x=>x.FechaActualizacion).HasPrecision(3); b.HasIndex(x=>x.Correo).IsUnique().HasDatabaseName("UQ_Usuarios_Correo"); b.HasIndex(x=>x.PropietarioId).IsUnique().HasFilter("[EsPropietario] = 1").HasDatabaseName("UQ_Usuarios_TitularPorPropietario"); b.HasIndex(x=>new{x.PropietarioId,x.Activo}).HasDatabaseName("IX_Usuarios_PropietarioId"); b.HasIndex(x=>x.RolId).HasDatabaseName("IX_Usuarios_RolId"); b.HasOne(x=>x.Propietario).WithMany(x=>x.Usuarios).HasForeignKey(x=>x.PropietarioId).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_Usuarios_Propietarios"); b.HasOne(x=>x.Rol).WithMany(x=>x.Usuarios).HasForeignKey(x=>x.RolId).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_Usuarios_Roles"); b.HasOne(x=>x.TelefonoPais).WithMany(x=>x.Usuarios).HasForeignKey(x=>x.TelefonoPaisCodigo).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_Usuarios_TelefonoPais"); } }
public sealed class AgendaConfiguration : IEntityTypeConfiguration<Agenda> { public void Configure(EntityTypeBuilder<Agenda> b) { b.ToTable("Agendas",t=>{t.HasCheckConstraint("CK_Agendas_Horario","HoraCierreDefault > HoraAperturaDefault");t.HasCheckConstraint("CK_Agendas_TelefonoPar","(TelefonoPaisCodigo IS NULL AND TelefonoContacto IS NULL) OR (TelefonoPaisCodigo IS NOT NULL AND TelefonoContacto IS NOT NULL)");}); b.HasKey(x=>x.Id).HasName("PK_Agendas"); b.Property(x=>x.Nombre).HasMaxLength(150).IsRequired(); b.Property(x=>x.MonedaCodigo).HasColumnType("char(3)").HasMaxLength(3).IsFixedLength().IsUnicode(false).HasDefaultValue("MXN"); b.Property(x=>x.ZonaHoraria).HasMaxLength(64).IsRequired().HasDefaultValue("America/Matamoros"); b.Property(x=>x.NombreEventoDefault).HasMaxLength(150).HasDefaultValue("Evento"); b.Property(x=>x.MostrarNotaGeneral).HasDefaultValue(false); b.Property(x=>x.NotaGeneral).HasMaxLength(1000); b.Property(x=>x.NotaGeneralActualizadaEn).HasPrecision(3); b.Property(x=>x.TelefonoPaisCodigo).HasColumnType("char(2)").HasMaxLength(2).IsFixedLength().IsUnicode(false); b.Property(x=>x.TelefonoContacto).HasMaxLength(20); b.Property(x=>x.DireccionNegocio).HasMaxLength(200); b.Property(x=>x.HoraAperturaDefault).HasColumnType("time(0)").HasDefaultValue(new TimeSpan(9,0,0)); b.Property(x=>x.HoraCierreDefault).HasColumnType("time(0)").HasDefaultValue(new TimeSpan(22,0,0)); b.Property(x=>x.Activo).HasDefaultValue(true); b.Property(x=>x.FechaCreacion).HasPrecision(3).HasDefaultValueSql("SYSUTCDATETIME()"); b.Property(x=>x.FechaActualizacion).HasPrecision(3); b.HasIndex(x=>new{x.PropietarioId,x.Nombre}).IsUnique().HasDatabaseName("UQ_Agendas_Propietario_Nombre"); b.HasIndex(x=>new{x.PropietarioId,x.Activo}).HasDatabaseName("IX_Agendas_PropietarioId"); b.HasOne(x=>x.Propietario).WithMany(x=>x.Agendas).HasForeignKey(x=>x.PropietarioId).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_Agendas_Propietarios"); b.HasOne(x=>x.Moneda).WithMany(x=>x.Agendas).HasForeignKey(x=>x.MonedaCodigo).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_Agendas_Monedas"); b.HasOne(x=>x.TelefonoPais).WithMany(x=>x.AgendasTelefono).HasForeignKey(x=>x.TelefonoPaisCodigo).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_Agendas_TelefonoPais"); b.HasOne(x=>x.NotaGeneralUsuario).WithMany(x=>x.AgendasNotaGeneral).HasForeignKey(x=>x.NotaGeneralUsuarioId).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_Agendas_NotaGeneralUsuario"); } }
public sealed class UsuarioAgendaConfiguration : IEntityTypeConfiguration<UsuarioAgenda> { public void Configure(EntityTypeBuilder<UsuarioAgenda> b) { b.ToTable("UsuarioAgendas"); b.HasKey(x=>new{x.UsuarioId,x.AgendaId}).HasName("PK_UsuarioAgendas"); b.Property(x=>x.FechaAsignacion).HasPrecision(3).HasDefaultValueSql("SYSUTCDATETIME()"); b.HasIndex(x=>x.AgendaId).HasDatabaseName("IX_UsuarioAgendas_AgendaId"); b.HasOne(x=>x.Usuario).WithMany(x=>x.UsuarioAgendas).HasForeignKey(x=>x.UsuarioId).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_UsuarioAgendas_Usuarios"); b.HasOne(x=>x.Agenda).WithMany(x=>x.UsuarioAgendas).HasForeignKey(x=>x.AgendaId).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_UsuarioAgendas_Agendas"); } }
public sealed class RefreshTokenConfiguration : IEntityTypeConfiguration<RefreshToken> { public void Configure(EntityTypeBuilder<RefreshToken> b) { b.ToTable("RefreshTokens"); b.HasKey(x=>x.Id).HasName("PK_RefreshTokens"); b.Property(x=>x.TokenHash).HasMaxLength(128).IsRequired(); b.Property(x=>x.Recordarme).HasDefaultValue(false); b.Property(x=>x.ExpiraEn).HasPrecision(3); b.Property(x=>x.CreadoEn).HasPrecision(3).HasDefaultValueSql("SYSUTCDATETIME()"); b.Property(x=>x.RevocadoEn).HasPrecision(3); b.Property(x=>x.ReemplazadoPorTokenHash).HasMaxLength(128); b.Property(x=>x.IpCreacion).HasMaxLength(45); b.Property(x=>x.UserAgent).HasMaxLength(256); b.HasIndex(x=>x.TokenHash).IsUnique().HasDatabaseName("UQ_RefreshTokens_TokenHash"); b.HasIndex(x=>new{x.UsuarioId,x.ExpiraEn}).HasFilter("[RevocadoEn] IS NULL").HasDatabaseName("IX_RefreshTokens_Usuario_Activos"); b.HasOne(x=>x.Usuario).WithMany(x=>x.RefreshTokens).HasForeignKey(x=>x.UsuarioId).OnDelete(DeleteBehavior.NoAction).HasConstraintName("FK_RefreshTokens_Usuarios"); } }
